  15 // Runs the server until it exits; resolves with { code, stdout, stderr }.
  16 export function runToExit(env, cwd = ROOT) {
  17   return new Promise((resolve) => {
  18     const child = spawn(process.execPath, [SERVER], { cwd, env: { ...process.env, ...env } });
  19     let stdout = '';
  20     let stderr = '';
  21     child.stdout.on('data', (d) => (stdout += d));
  22     child.stderr.on('data', (d) => (stderr += d));
  23     const timer = setTimeout(() => child.kill(), 5000);
  24     child.on('exit', (code) => {
  25       clearTimeout(timer);
  26       resolve({ code, stdout, stderr });
  27     });
  28   });
  29 }
