  31 // Starts the server and resolves once it is listening.
  32 export function startServer(env = {}, cwd = ROOT) {
  33   return new Promise((resolve, reject) => {
  34     const child = spawn(process.execPath, [SERVER], {
  35       cwd,
  36       env: { ...process.env, PORT: '0', ...env },
  37     });
  38     let stdout = '';
  39     let stderr = '';
  40     child.stderr.on('data', (d) => (stderr += d));
  41     child.stdout.on('data', (d) => {
  42       stdout += d;
  43       const m = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/.exec(stdout);
  44       if (m) {
  45         const port = Number(m[1]);
  46         const base = `http://127.0.0.1:${port}`;
  47         resolve({
  48           child,
  49           port,
  50           base,
  51           get stdout() { return stdout; },
  52           stop: () => new Promise((r) => {
  53             if (child.exitCode !== null) return r();
  54             child.once('exit', r);
  55             child.kill();
  56           }),
  57         });
  58       }
  59     });
  60     child.on('exit', (code) => reject(new Error(`server exited ${code}: ${stderr}`)));
  61   });
  62 }
