  64 export async function api(base, method, urlPath, { body, headers } = {}) {
  65   const init = { method, headers: { ...headers } };
  66   if (body !== undefined) {
  67     init.body = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
  68     if (!('Content-Type' in init.headers)) init.headers['Content-Type'] = 'application/json';
  69   }
  70   const res = await fetch(base + urlPath, init);
  71   const text = await res.text();
  72   let json;
  73   try {
  74     json = text === '' ? undefined : JSON.parse(text);
  75   } catch {
  76     json = undefined;
  77   }
  78   return { status: res.status, headers: res.headers, text, json };
  79 }
