  81 // Sends a raw request target (no normalisation) and returns status and body.
  82 export function rawRequest(port, method, target, { headers = {}, body } = {}) {
  83   return new Promise((resolve, reject) => {
  84     const socket = net.connect(port, '127.0.0.1');
  85     let data = '';
  86     const lines = [`${method} ${target} HTTP/1.1`, 'Host: localhost', 'Connection: close'];
  87     for (const [k, v] of Object.entries(headers)) lines.push(`${k}: ${v}`);
  88     if (body !== undefined) lines.push(`Content-Length: ${Buffer.byteLength(body)}`);
  89     socket.on('connect', () => {
  90       socket.write(lines.join('\r\n') + '\r\n\r\n');
  91       if (body !== undefined) socket.write(body);
  92     });
  93     socket.on('data', (d) => (data += d));
  94     socket.on('end', () => {
  95       const [head, ...rest] = data.split('\r\n\r\n');
  96       const status = Number(head.split(' ')[1]);
  97       resolve({ status, head, body: rest.join('\r\n\r\n') });
  98     });
  99     socket.on('error', reject);
 100   });
 101 }
