 25 const MSG = Object.freeze({
 26   contentType: 'content type must be application/json',
 27   tooLarge: 'body too large',
 28   notObject: 'body must be a JSON object',
 29   room: 'room must be one of Aurora, Borealis, Cosmos',
 30   title: 'title must be 1 to 80 characters',
 31   date: 'date must be a valid YYYY-MM-DD date',
 32   start: 'start must be HH:MM',
 33   end: 'end must be HH:MM',
 34   order: 'end must be after start',
 35   bookingNotFound: 'booking not found',
