 92 // ---------- data file ----------
 93 
 94 const emptyState = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
 95 
 96 function isStoredBooking(b) {
 97   if (!isPlainObject(b)) return false;
 98   const keys = Object.keys(b);
 99   if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
100   return Number.isSafeInteger(b.id) && b.id >= 1 && ROOMS.includes(b.room)
101     && isValidTitle(b.title) && b.title === b.title.trim()
102     && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
103 }
104 
105 /** Strict check that `data` is exactly the layout this server writes. */
106 function isValidLayout(data) {
107   if (!isPlainObject(data)) return false;
108   const keys = Object.keys(data);
109   if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return false;
110   const { nextId, bookings } = data;
111   if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
112   if (!bookings.every(isStoredBooking)) return false;
113   const ids = new Set(bookings.map((b) => b.id));
114   if (ids.size !== bookings.length || bookings.some((b) => b.id >= nextId)) return false;
115   return !bookings.some((b, i) => bookings.slice(i + 1).some((other) => overlaps(b, other)));
