169 function send(res, status, payload) {
170   if (status === 204) {
171     res.writeHead(204);
172     res.end();
173     return;
174   }
175   const body = JSON.stringify(payload);
176   res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
177   res.end(body);
178 }
179 
180 const sendError = (res, status, message) => send(res, status, { error: message });
