100 // ---------- routing ----------
101 
102 function splitTarget(target) {
103   const q = target.indexOf('?');
104   return q === -1 ? { path: target, query: null } : { path: target.slice(0, q), query: target.slice(q + 1) };
105 }
106 
107 /** Returns { handler, params } or throws HttpError 404/405. */
108 function route(method, pathname, routes) {
109   if (Object.hasOwn(routes, pathname)) {
110     const handler = routes[pathname][method];
111     if (!handler) throw new HttpError(405, 'method not allowed');
112     return { handler, id: null };
113   }
114   if (pathname.startsWith(BOOKINGS_PREFIX)) {
115     const id = pathname.slice(BOOKINGS_PREFIX.length);
116     if (id.length > 0 && !id.includes('/')) {
117       if (method !== 'DELETE') throw new HttpError(405, 'method not allowed');
118       return { handler: 'deleteBooking', id };
119     }
120   }
121   throw new HttpError(404, 'not found');
122 }
