148 function checkContentType(header) {
149   const media = isString(header) ? header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '').toLowerCase() : '';
150   if (media !== 'application/json') throw new HttpError(415, 'content type must be application/json');
