153 function parseBookingInput(body) {
154   let data;
155   try {
156     data = JSON.parse(body.toString('utf8'));
157   } catch {
158     throw new HttpError(400, 'body must be a JSON object');
159   }
160   if (!isPlainObject(data)) throw new HttpError(400, 'body must be a JSON object');
161   const [room, title, date, start, end] = ['room', 'title', 'date', 'start', 'end'].map((k) => ownValue(data, k));
162   if (!isString(room) || !ROOMS.includes(room)) throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
163   if (!isValidTitle(title)) throw new HttpError(400, 'title must be 1 to 80 characters');
164   if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
165   if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
166   if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
167   if (end <= start) throw new HttpError(400, 'end must be after start');
168   return { room, title: title.trim(), date, start, end };
169 }
